import { GoogleGenAI } from "@google/genai";

// Ensure API key is available
const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

export const generateCreativeIdea = async (topic: string): Promise<string> => {
  if (!apiKey) {
    return "API Key is missing. Please configure your environment.";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a unique, avant-garde creative project idea based on the topic: "${topic}". 
      Keep it concise (under 50 words), inspiring, and abstract. 
      Format: "Title: [Title] \n Concept: [Concept]"`,
      config: {
        temperature: 0.9,
      }
    });

    return response.text || "Could not generate an idea at this time.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "An error occurred while connecting to the creative mind.";
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  children, 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-full font-medium transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-background disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-white text-black hover:bg-gray-200 focus:ring-white",
    secondary: "bg-zinc-800 text-white hover:bg-zinc-700 focus:ring-zinc-700",
    outline: "border border-zinc-700 text-zinc-300 hover:border-zinc-500 hover:text-white bg-transparent",
    ghost: "text-zinc-400 hover:text-white hover:bg-zinc-800/50",
  };

  const sizes = {
    sm: "h-8 px-4 text-xs",
    md: "h-10 px-6 text-sm",
    lg: "h-12 px-8 text-base",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React, { useState, useEffect } from 'react';
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { Menu, X, Sparkles } from 'lucide-react';
import { Button } from './ui/Button';

export const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { label: 'Home', path: '/' },
    { label: 'Tools', path: '/tools' },
    { label: 'Work', path: '/work' },
    { label: 'Services', path: '/services' },
  ];

  const handleMobileNav = (path: string) => {
    navigate(path);
    setIsMobileMenuOpen(false);
  };

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 border-b ${
        isScrolled 
          ? 'bg-background/80 backdrop-blur-md border-zinc-800 py-3' 
          : 'bg-transparent border-transparent py-5'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
        {/* Logo */}
        <NavLink to="/" className="flex items-center gap-2 group">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white shadow-lg shadow-indigo-500/20 group-hover:shadow-indigo-500/40 transition-all">
             <Sparkles size={18} fill="currentColor" className="text-white" />
          </div>
          <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-zinc-400">
            Creatush
          </span>
        </NavLink>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <NavLink 
              key={link.path} 
              to={link.path}
              className={({ isActive }) => 
                `text-sm font-medium transition-colors hover:text-white ${
                  isActive ? 'text-white' : 'text-zinc-400'
                }`
              }
            >
              {link.label}
            </NavLink>
          ))}
          <Button variant="primary" size="sm" onClick={() => navigate('/tools')}>
            Get Started
          </Button>
        </div>

        {/* Mobile Menu Toggle */}
        <button 
          className="md:hidden text-zinc-300 hover:text-white"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Nav Dropdown */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 right-0 bg-zinc-950 border-b border-zinc-800 md:hidden animate-fade-in-up">
          <div className="flex flex-col p-6 gap-4">
            {navLinks.map((link) => (
              <button
                key={link.path}
                onClick={() => handleMobileNav(link.path)}
                className={`text-left text-lg font-medium ${
                  location.pathname === link.path ? 'text-white' : 'text-zinc-400'
                }`}
              >
                {link.label}
              </button>
            ))}
            <Button className="w-full mt-4" onClick={() => handleMobileNav('/tools')}>
              Get Started
            </Button>
          </div>
        </div>
      )}
    </nav>
  );
};

import React, { useState } from 'react';
import { PenTool, Cpu, Image, Wand2, ArrowRight, Loader2, RefreshCw } from 'lucide-react';
import { Button } from '../components/ui/Button';
import { generateCreativeIdea } from '../services/geminiService';

export const Tools: React.FC = () => {
  const [activeToolId, setActiveToolId] = useState<string | null>(null);
  const [aiInput, setAiInput] = useState('');
  const [aiOutput, setAiOutput] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const tools = [
    {
      id: 'ai-brief',
      name: 'Magic Brief Generator',
      description: 'Generate avant-garde creative project briefs instantly using Gemini AI.',
      icon: Wand2,
      isAiPowered: true,
    },
    {
      id: 'palette',
      name: 'Color Alchemy',
      description: 'Extract dominant color palettes from any image URL.',
      icon: Image,
    },
    {
      id: 'optimizer',
      name: 'Asset Optimizer',
      description: 'Compress and optimize 3D assets and textures for web.',
      icon: Cpu,
    },
    {
      id: 'mockup',
      name: 'Instant Mockup',
      description: 'Place your designs into high-fidelity device frames.',
      icon: PenTool,
    },
  ];

  const handleLaunch = (id: string) => {
    setActiveToolId(id);
    setAiOutput(null);
    setAiInput('');
  };

  const handleAiGenerate = async () => {
    if (!aiInput.trim()) return;
    setIsLoading(true);
    const result = await generateCreativeIdea(aiInput);
    setAiOutput(result);
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen pt-32 pb-20 px-6">
      <div className="max-w-7xl mx-auto">
        <div className="mb-16">
          <h1 className="text-4xl font-bold text-white mb-4">Creative Tools</h1>
          <p className="text-zinc-400 max-w-2xl">
            A suite of powerful utilities designed to accelerate your workflow. 
            From AI generation to asset management.
          </p>
        </div>

        {/* Active Tool View (Modal-ish overlay or expanded section) */}
        {activeToolId === 'ai-brief' && (
          <div className="mb-16 bg-zinc-900 border border-zinc-800 rounded-2xl p-8 animate-fade-in-up">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-2xl font-bold text-white flex items-center gap-2">
                  <Wand2 className="text-indigo-500" /> Magic Brief Generator
                </h3>
                <p className="text-zinc-400 mt-2">Powered by Gemini 3 Flash Preview</p>
              </div>
              <button 
                onClick={() => setActiveToolId(null)}
                className="text-zinc-500 hover:text-white"
              >
                Close
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <label className="block text-sm font-medium text-zinc-300">Enter a topic or industry</label>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={aiInput}
                    onChange={(e) => setAiInput(e.target.value)}
                    placeholder="e.g., Sustainable Fashion, Cyberpunk City, Organic Coffee"
                    className="flex-1 bg-zinc-950 border border-zinc-800 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    onKeyDown={(e) => e.key === 'Enter' && handleAiGenerate()}
                  />
                  <Button onClick={handleAiGenerate} disabled={isLoading}>
                    {isLoading ? <Loader2 className="animate-spin" /> : 'Generate'}
                  </Button>
                </div>
                <p className="text-xs text-zinc-500">
                  Tip: Be abstract. The AI is tuned for avant-garde concepts.
                </p>
              </div>

              <div className="bg-zinc-950 rounded-xl p-6 border border-zinc-800 min-h-[200px] relative">
                <h4 className="text-zinc-500 text-xs font-mono uppercase tracking-wider mb-4">Output Console</h4>
                {isLoading ? (
                  <div className="absolute inset-0 flex items-center justify-center">
                    <Loader2 className="animate-spin text-indigo-500 w-8 h-8" />
                  </div>
                ) : aiOutput ? (
                  <div className="prose prose-invert">
                    <p className="whitespace-pre-line text-zinc-200 leading-relaxed font-light text-lg">
                      {aiOutput}
                    </p>
                    <div className="mt-4 pt-4 border-t border-zinc-900 flex justify-end">
                      <button onClick={handleAiGenerate} className="text-xs text-indigo-400 hover:text-indigo-300 flex items-center gap-1">
                        <RefreshCw size={12} /> Regenerate
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center h-full text-zinc-700">
                    <Wand2 size={32} className="mb-2 opacity-20" />
                    <p className="text-sm">Ready to dream.</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Tools Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {tools.map((tool) => (
            <div 
              key={tool.id}
              className={`group p-6 rounded-2xl border transition-all duration-300 hover:-translate-y-1 ${
                activeToolId === tool.id 
                  ? 'bg-zinc-900 border-indigo-500/50 shadow-lg shadow-indigo-500/10' 
                  : 'bg-zinc-900/50 border-zinc-800 hover:border-zinc-700'
              }`}
            >
              <div className="w-12 h-12 rounded-xl bg-zinc-950 border border-zinc-800 flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                <tool.icon className={tool.isAiPowered ? "text-indigo-400" : "text-zinc-400"} />
              </div>
              <h3 className="text-xl font-semibold text-white mb-2 flex items-center gap-2">
                {tool.name}
                {tool.isAiPowered && (
                  <span className="px-2 py-0.5 rounded-full bg-indigo-500/10 text-indigo-400 text-[10px] uppercase font-bold tracking-wider border border-indigo-500/20">AI</span>
                )}
              </h3>
              <p className="text-zinc-400 text-sm mb-6 h-10">
                {tool.description}
              </p>
              <Button 
                variant={activeToolId === tool.id ? 'primary' : 'outline'} 
                size="sm" 
                className="w-full"
                onClick={() => handleLaunch(tool.id)}
                disabled={activeToolId !== null && activeToolId !== tool.id}
              >
                {activeToolId === tool.id ? 'Active' : 'Launch Tool'}
              </Button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

