  return null;
};

const BackgroundEffects = () => {
  return (
    <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
        {/* Subtle Grid Overlay */}
        <div className="absolute inset-0 bg-grid-pattern opacity-100 mix-blend-overlay"></div>

