  );
};

const ScrollProgress = () => {
    const { scrollYProgress } = useScroll();
    const scaleX = useSpring(scrollYProgress, {
        stiffness: 100,
        damping: 30,
        restDelta: 0.001
    });

    return (
        <motion.div
            className="fixed top-0 left-0 right-0 h-[2px] bg-purple-500 origin-left z-[100]"
            style={{ scaleX }}
        />
    );
};

const App: React.FC = () => {
  return (
    <HashRouter>
